import test from'node:test';import assert from'node:assert/strict';import{readFileSync}from'node:fs';import{createHash}from'node:crypto';import{JSDOM}from'jsdom';import{createGameEntry}from'../public/games/shared/entry-shell.mjs';import{createDialogController}from'../public/games/long-jump/dialogs.mjs';import{createHelpCoordinator,suspendHelpPresentation}from'../public/games/shared/help-coordinator.mjs';
