test('exact preview dependency bundle and every other main Jump file are preserved',()=>{const m=JSON.parse(read('docs/hurdles-main/SOURCE-MANIFEST.json'));const promoted=p=>m.productionLeaderboard.files.find(x=>x.path===p);const current=(p,prior)=>{const a=m.productionCounts.files.find(x=>x.path===p);if(a)assert.equal(a.beforeSha256,prior);const correction=m.mainNavDiagnostic?.files.find(x=>x.path===p);if(correction)assert.equal(correction.beforeSha256,a?.sha256||prior);return correction?.sha256||a?.sha256||prior;};for(const f of m.files){const a=promoted(f.path);if(a)assert.equal(a.beforeSha256,f.sha256);assert.equal(hash(readBeforeV2(f.path)),current(f.path,a?.sha256||f.sha256),f.path);}for(const f of m.originalJump){let bytes=readBeforeV2(f.path);const adaptation=promoted(f.path);if(adaptation){assert.equal(hash(bytes),current(f.path,adaptation.sha256));continue;}if(f.adapted)bytes=Buffer.from(bytes.toString().replace('button:not([disabled]),a[href],summary,input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]','button:not([disabled]),a[href],summary'));const icon=m.productionIcons?.headOnly.find(x=>x.path===f.path);if(icon){assert.equal(icon.beforeSha256,f.sha256);assert.equal(hash(bytes),icon.afterSha256,f.path);assert.equal(hash(Buffer.from(bytes.toString().split('</head>')[1])),icon.bodySha256);}else assert.equal(hash(bytes),f.sha256,f.path);}assert.equal(hash(read('public/assets/favicon.svg')),m.originalFaviconSha256);});
